//! Flattening registry and person data into LaTeX command definitions.

use crate::domain::escape;
use serde_yaml::Value;
use std::collections::BTreeMap;

/// The command definitions a document is rendered against.
///
/// A `BTreeMap` rather than a hash map so the generated file is byte-stable:
/// the register records the hash of the rendered PDF, and a data file whose
/// line order varied between runs would make that hash meaningless.
#[derive(Debug, Default, Clone)]
pub struct Definitions {
    values: BTreeMap<String, String>,
    flags: BTreeMap<String, bool>,
}

impl Definitions {
    /// An empty set.
    #[must_use]
    pub fn new() -> Self {
        Self::default()
    }

    /// Define a value, escaping it for LaTeX.
    pub fn set(&mut self, name: impl Into<String>, value: &str) {
        self.values.insert(name.into(), escape::tex(value));
    }

    /// Define a value that is already valid LaTeX, such as a list body.
    pub fn set_raw(&mut self, name: impl Into<String>, latex: impl Into<String>) {
        self.values.insert(name.into(), latex.into());
    }

    /// Define a value only if it is not already defined.
    pub fn set_default(&mut self, name: &str, value: &str) {
        if !self.values.contains_key(name) {
            self.set(name.to_owned(), value);
        }
    }

    /// Look a value up, for tests and for copying one name onto another.
    #[must_use]
    pub fn get(&self, name: &str) -> Option<&str> {
        self.values.get(name).map(String::as_str)
    }

    /// Copy a definition to a second name, if the source exists.
    pub fn alias(&mut self, from: &str, to: &str) {
        if let Some(v) = self.values.get(from).cloned() {
            self.values.insert(to.to_owned(), v);
        }
    }

    /// Number of defined values, excluding flags.
    #[must_use]
    pub fn len(&self) -> usize {
        self.values.len()
    }

    /// Whether anything is defined.
    #[must_use]
    pub fn is_empty(&self) -> bool {
        self.values.is_empty() && self.flags.is_empty()
    }

    /// Take every definition from another set, overwriting on collision.
    pub fn merge(&mut self, other: &Self) {
        for (k, v) in &other.values {
            self.values.insert(k.clone(), v.clone());
        }
        for (k, v) in &other.flags {
            self.flags.insert(k.clone(), *v);
        }
    }

    /// Walk a YAML value, defining a command for each leaf.
    ///
    /// Booleans become TeX conditionals rather than values. Printing a
    /// boolean would put the literal text `true` on a form where a tick was
    /// meant, which is the kind of defect that reaches a signature.
    pub fn absorb(&mut self, prefix: &str, value: &Value) {
        let Some(map) = value.as_mapping() else {
            return;
        };
        for (key, val) in map {
            let Some(key) = key.as_str() else { continue };
            let name = format!("{prefix}{}", escape::command_name(key));
            match val {
                Value::Bool(b) => {
                    self.flags.insert(name, *b);
                }
                Value::Mapping(_) => self.absorb(&name, val),
                Value::Sequence(items) => {
                    let mut body = String::new();
                    for text in items.iter().filter_map(scalar_text) {
                        body.push_str("\\item ");
                        body.push_str(&escape::tex(&text));
                    }
                    // An empty list still needs a body: \begin{itemize} with
                    // no \item is a LaTeX error, and an empty section is a
                    // better failure than a broken build at issuance time.
                    self.set_raw(
                        format!("{name}Items"),
                        if body.is_empty() {
                            "\\item ~".to_owned()
                        } else {
                            body
                        },
                    );
                    self.set_raw(format!("{name}Count"), items.len().to_string());
                }
                Value::Null => {}
                other => {
                    if let Some(text) = scalar_text(other) {
                        self.set(name, &text);
                    }
                }
            }
        }
    }

    /// Render the `dkdata.tex` the document class loads.
    ///
    /// `\expandafter\def\csname NAME\endcsname` rather than `\newcommand`
    /// so a name may be defined without checking whether the class already
    /// provided a drafting default for it.
    #[must_use]
    pub fn to_tex(&self) -> String {
        use std::fmt::Write as _;
        let mut out = String::from(
            "% GENERATED by docket -- do not edit.\n\
             % Values come from registry/*.yaml and the person record.\n\
             \\makeatletter\n",
        );
        // Writing to a String cannot fail; the Result is discarded rather
        // than unwrapped because `unwrap_used` is denied crate-wide.
        for (name, value) in &self.values {
            let _ = writeln!(
                out,
                "\\expandafter\\def\\csname {name}\\endcsname{{{value}}}"
            );
        }
        for (name, enabled) in &self.flags {
            let _ = writeln!(out, "\\expandafter\\newif\\csname if{name}\\endcsname");
            if *enabled {
                // \newif\ifFoo defines \Footrue; call the setter rather than
                // \let-ing the conditional, which breaks under \expandafter.
                let _ = writeln!(out, "\\csname {name}true\\endcsname");
            }
        }
        out.push_str("\\makeatother\n");
        out
    }
}

/// Text of a scalar YAML value, or `None` if it is not scalar.
fn scalar_text(value: &Value) -> Option<String> {
    match value {
        Value::String(s) => Some(s.clone()),
        Value::Number(n) => Some(n.to_string()),
        Value::Bool(b) => Some(b.to_string()),
        _ => None,
    }
}

#[cfg(test)]
// A test that cannot assert an expected value is not a test. The lint stays
// denied for the crate; only assertions inside test modules are exempt.
#[allow(clippy::expect_used, clippy::unwrap_used, clippy::indexing_slicing)]
mod tests {
    use super::Definitions;
    use serde_yaml::Value;

    fn yaml(src: &str) -> Value {
        serde_yaml::from_str(src).expect("fixture parses")
    }

    #[test]
    fn nested_maps_become_camel_case_names() {
        let mut d = Definitions::new();
        d.absorb("dk", &yaml("org:\n  legal_status: In Process\n"));
        assert_eq!(d.get("dkOrgLegalStatus"), Some("In Process"));
    }

    #[test]
    fn values_are_escaped_on_the_way_in() {
        let mut d = Definitions::new();
        d.absorb("dk", &yaml("org:\n  tagline: Technology & Software\n"));
        assert_eq!(d.get("dkOrgTagline"), Some(r"Technology \& Software"));
    }

    #[test]
    fn booleans_become_conditionals_not_printed_text() {
        let mut d = Definitions::new();
        d.absorb("dk", &yaml("edu:\n  enrolled: true\n  credit: false\n"));
        let tex = d.to_tex();
        assert!(
            d.get("dkEduEnrolled").is_none(),
            "a bool must not become a value"
        );
        assert!(tex.contains(r"\csname dkEduEnrolledtrue\endcsname"));
        assert!(!tex.contains(r"\csname dkEduCredittrue\endcsname"));
        assert!(tex.contains(r"\expandafter\newif\csname ifdkEduCredit\endcsname"));
    }

    #[test]
    fn lists_become_item_bodies_and_counts() {
        let mut d = Definitions::new();
        d.absorb("dk", &yaml("cert:\n  areas: [Rust, LaTeX]\n"));
        assert_eq!(d.get("dkCertAreasItems"), Some(r"\item Rust\item LaTeX"));
        assert_eq!(d.get("dkCertAreasCount"), Some("2"));
    }

    #[test]
    fn an_empty_list_still_produces_a_valid_itemize_body() {
        // \begin{itemize}\end{itemize} with no \item is a LaTeX error.
        let mut d = Definitions::new();
        d.absorb("dk", &yaml("cert:\n  areas: []\n"));
        assert_eq!(d.get("dkCertAreasItems"), Some(r"\item ~"));
    }

    #[test]
    fn nulls_define_nothing_so_the_build_fails_loudly() {
        // A null that became an empty string would print a blank space on a
        // signed document. Leaving it undefined fails the build instead.
        let mut d = Definitions::new();
        d.absorb("dk", &yaml("org:\n  cin: null\n"));
        assert!(d.get("dkOrgCin").is_none());
    }

    #[test]
    fn output_is_byte_stable_regardless_of_insertion_order() {
        let mut a = Definitions::new();
        a.set("dkZ", "1");
        a.set("dkA", "2");
        let mut b = Definitions::new();
        b.set("dkA", "2");
        b.set("dkZ", "1");
        assert_eq!(a.to_tex(), b.to_tex());
    }

    #[test]
    fn alias_copies_a_definition() {
        let mut d = Definitions::new();
        d.set("dkOrgEmail", "legal@paridyum.com");
        d.alias("dkOrgEmail", "dkEmail");
        assert_eq!(d.get("dkEmail"), Some("legal@paridyum.com"));
        d.alias("dkMissing", "dkNope");
        assert!(d.get("dkNope").is_none());
    }
}
